get() {
      visits.push(`${name}:get`);
      harness.event(`get:${name}`, { sameReceiver: this === object });
      if (scenario.fail === `${name}:get`)
        harness.fail(`throw:${name}:get`);
      return function backupMethod(...args) {
        visits.push(`${name}:call`);
        harness.event(`call:${name}`, { sameReceiver: this === object, arguments: runtime.value(args) }, { sameReceiver: this === object, arguments: native.snapshot(args) });
        assert.equal(this, object);
        assert.equal(args.length, 1);
        if (scenario.fail === `${name}:call`)
          harness.fail(`throw:${name}:call`);
        return body(args);
      };
    }

